import Foundation
import ObjectiveC

// Load framework
let path = "/Library/Developer/PrivateFrameworks/CoreSimulator.framework/CoreSimulator"
guard Bundle(path: path)?.load() != nil else { print("load failed"); exit(1) }

func dumpClass(_ name: String) {
    guard let cls: AnyClass = objc_getClass(name) else { print("no class \(name)"); return }
    print("=== \(name) ===")
    var count: UInt32 = 0
    if let methods = class_copyMethodList(cls, &count) {
        for i in 0..<Int(count) {
            let m = methods[i]
            let sel = method_getName(m)
            let name = NSStringFromSelector(sel)
            if name.lowercased().contains("touch") || name.lowercased().contains("mouse") || name.lowercased().contains("send") || name.lowercased().contains("input") {
                print("  \(name)")
            }
        }
        free(methods)
    }
}

for c in ["SimDevice", "SimDeviceIO", "SimDeviceTouch", "SimDeviceInput"] {
    dumpClass(c)
}
EOF
xcrun swift /tmp/dumpmethods.swift 2>&1 | head -60

