import Foundation
import ObjectiveC

let path = "/Library/Developer/PrivateFrameworks/CoreSimulator.framework/Versions/A/CoreSimulator"
guard dlopen(path, RTLD_NOW) != nil else { print("err"); exit(1) }

func dumpAll(_ name: String) {
    guard let cls = objc_getClass(name) as? AnyClass else { print("no class \(name)"); return }
    print("=== \(name) (\(class_getSuperclass(cls) != nil ? String(cString: class_getName(class_getSuperclass(cls)!)) : "nil")) ===")
    var count: UInt32 = 0
    if let methods = class_copyMethodList(cls, &count) {
        for i in 0..<Int(count) {
            print("  " + NSStringFromSelector(method_getName(methods[i])))
        }
        free(methods)
    }
}
dumpAll("SimDevice")
dumpAll("SimDeviceIO")
EOF
